#!/usr/bin/env bash
# Bundle item 180_agri37_39_live20_post_videos (Agriculture archive thread, generated 22 Nov 2569)
# Agriculture main + livestock subcommittee videos; in this item: main 37 (3:04), 38 (3:45), 39 (3:06) + livestock 20 (2:31) POST videos
# Puts Agriculture main-committee videos on parliamentx.com/agriculture/2569.
# 1080x1920, Thai voice + English subtitles burned in (one version), kind="pre"/"post". No private names, no company names,
# no MP named as a bill's proposer (checked in each video's legal pack).
# Generated by committees/agri/tools/gen_bundle_item_videos.py from the csite build (committee.py VIDEOS / SUB_VIDEOS).
# Surgical: copies mp4/vtt/poster files, replaces only the "media" field of those meetings in the DATA line of
# agriculture/2569/index.html and in meetings.json, fills the CAPS caption tracks,
# makes the video share pages (video_share.py, CARD_BIG=1), re-applies no_video_dl to s/, then refreshes the home page
# newest-4 video list and the Agriculture 2569 snapshot "v".
# Idempotent; no git, no network. Needs $HUB $BUILD.
set -euo pipefail
: "${HUB:?HUB not set}"; BUILD=${BUILD:-/mnt/project-files/archive/build}
SRC="${ITEM_FILES:-/mnt/project-files/archive/bundle/items/180_agri37_39_live20_post_videos_files}"
L="$HUB/agriculture/2569"
test -f "$L/index.html" -a -f "$L/meetings.json" || { echo "agri_videos: $L pages missing" >&2; exit 1; }
test -f "$HUB/index.html" || { echo "agri_videos: hub index.html missing" >&2; exit 1; }
# files must be whole: 1080x1920 video of the listed length, WEBVTT captions
for v in sub-livestock-v20:151 v37:184 v38:225 v39:186; do f=${v%%:*}; want=${v##*:}
  test -s "$SRC/$f.mp4" -a -s "$SRC/$f.th.vtt" || { echo "agri_videos: $SRC/$f missing" >&2; exit 1; }
  dur=$(ffprobe -v error -show_entries format=duration -of csv=p=0 "$SRC/$f.mp4")
  python3 -c "import sys; sys.exit(0 if abs(float('$dur')-$want)<1.5 else 1)" || { echo "agri_videos: $f length $dur, expected ~$want s" >&2; exit 1; }
  wh=$(ffprobe -v error -select_streams v:0 -show_entries stream=width,height -of csv=p=0 "$SRC/$f.mp4"); [ "$wh" = "1080,1920" ] || { echo "agri_videos: $f size $wh" >&2; exit 1; }
  head -1 "$SRC/$f.th.vtt" | grep -q '^WEBVTT' || { echo "agri_videos: $f vtt header" >&2; exit 1; }
done
mkdir -p "$L/media" "$L/img"
for f in sub-livestock-v20.mp4 sub-livestock-v20.th.vtt v37.mp4 v37.th.vtt v38.mp4 v38.th.vtt v39.mp4 v39.th.vtt; do cmp -s "$SRC/$f" "$L/media/$f" || cp -f "$SRC/$f" "$L/media/$f"; cmp -s "$SRC/$f" "$L/media/$f"; done
for f in poster-sub-livestock-20.jpg poster37.jpg poster38.jpg poster39.jpg; do cmp -s "$SRC/$f" "$L/img/$f" || cp -f "$SRC/$f" "$L/img/$f"; cmp -s "$SRC/$f" "$L/img/$f"; done
python3 - "$HUB" <<'PY'
import json, os, sys
HUB = sys.argv[1]; L = os.path.join(HUB, 'agriculture', '2569')
D = json.loads(r"""{
"MEDIA": {
"index.html": {
"39|2026-11-16": {
"video": {
"src": "media/v39.mp4",
"poster": "img/poster39.jpg",
"vtt": "media/v39.th.vtt",
"kind": "post",
"label": "วิดีโอสรุปผลการประชุม",
"dur": "3:06",
"cc": "เสียงบรรยายภาษาไทย มีคำบรรยายภาษาอังกฤษในวิดีโอ",
"ck": "39"
},
"videos": [
{
"src": "media/v39.mp4",
"poster": "img/poster39.jpg",
"vtt": "media/v39.th.vtt",
"kind": "post",
"label": "วิดีโอสรุปผลการประชุม",
"dur": "3:06",
"cc": "เสียงบรรยายภาษาไทย มีคำบรรยายภาษาอังกฤษในวิดีโอ",
"ck": "39"
},
{
"src": "/video-1/agriculture/2569/media/v39pre.mp4",
"size": 3583230,
"poster": "img/poster39pre.jpg",
"vtt": "media/v39pre.th.vtt",
"kind": "pre",
"label": "วิดีโอก่อนการประชุม",
"dur": "1:25",
"cc": "เสียงบรรยายภาษาไทย มีคำบรรยายภาษาอังกฤษในวิดีโอ",
"ck": "39p"
}
]
},
"38|2026-11-09": {
"video": {
"src": "media/v38.mp4",
"poster": "img/poster38.jpg",
"vtt": "media/v38.th.vtt",
"kind": "post",
"label": "วิดีโอสรุปผลการประชุม",
"dur": "3:45",
"cc": "เสียงบรรยายภาษาไทย มีคำบรรยายภาษาอังกฤษในวิดีโอ",
"ck": "38"
},
"videos": [
{
"src": "media/v38.mp4",
"poster": "img/poster38.jpg",
"vtt": "media/v38.th.vtt",
"kind": "post",
"label": "วิดีโอสรุปผลการประชุม",
"dur": "3:45",
"cc": "เสียงบรรยายภาษาไทย มีคำบรรยายภาษาอังกฤษในวิดีโอ",
"ck": "38"
}
]
},
"37|2026-11-02": {
"video": {
"src": "media/v37.mp4",
"poster": "img/poster37.jpg",
"vtt": "media/v37.th.vtt",
"kind": "post",
"label": "วิดีโอสรุปผลการประชุม",
"dur": "3:04",
"cc": "เสียงบรรยายภาษาไทย มีคำบรรยายภาษาอังกฤษในวิดีโอ",
"ck": "37"
},
"videos": [
{
"src": "media/v37.mp4",
"poster": "img/poster37.jpg",
"vtt": "media/v37.th.vtt",
"kind": "post",
"label": "วิดีโอสรุปผลการประชุม",
"dur": "3:04",
"cc": "เสียงบรรยายภาษาไทย มีคำบรรยายภาษาอังกฤษในวิดีโอ",
"ck": "37"
}
]
}
},
"sub-livestock.html": {
"20|2026-11-18": {
"video": {
"src": "media/sub-livestock-v20.mp4",
"poster": "img/poster-sub-livestock-20.jpg",
"vtt": "media/sub-livestock-v20.th.vtt",
"kind": "post",
"label": "วิดีโอสรุปผลการประชุม",
"dur": "2:31",
"cc": "เสียงบรรยายภาษาไทย มีคำบรรยายภาษาอังกฤษในวิดีโอ",
"ck": "livestock-20"
},
"videos": [
{
"src": "media/sub-livestock-v20.mp4",
"poster": "img/poster-sub-livestock-20.jpg",
"vtt": "media/sub-livestock-v20.th.vtt",
"kind": "post",
"label": "วิดีโอสรุปผลการประชุม",
"dur": "2:31",
"cc": "เสียงบรรยายภาษาไทย มีคำบรรยายภาษาอังกฤษในวิดีโอ",
"ck": "livestock-20"
}
]
}
}
},
"CAPK": {
"index.html": {
"39": "media/v39.th.vtt",
"39p": "media/v39pre.th.vtt",
"38": "media/v38.th.vtt",
"37": "media/v37.th.vtt"
},
"sub-livestock.html": {
"livestock-20": "media/sub-livestock-v20.th.vtt"
}
},
"JSONS": {
"index.html": "meetings.json",
"sub-livestock.html": "sub-livestock.json"
}
}""")
MEDIA, CAPK, JSONS = D['MEDIA'], D['CAPK'], D['JSONS']
CMP = dict(ensure_ascii=False, separators=(',', ':'))
ser = lambda a: json.dumps(a, **CMP).replace('</', '<\\/')
changed = []

def put(path, text):
    old = open(path, encoding='utf-8').read()
    if old != text:
        open(path, 'w', encoding='utf-8').write(text); changed.append(os.path.relpath(path, HUB))

def sized(md):
    md = json.loads(json.dumps(md))
    for v in [md['video']] + md['videos']:
        if v['src'].startswith('/video-'):   # already live in a video repo (39 pre): keep its link and size
            continue
        v['size'] = os.path.getsize(os.path.join(L, v['src']))
    return md

def jline(lines, prefix, dump):
    idx = [i for i, l in enumerate(lines) if l.startswith(prefix)]
    assert len(idx) == 1, f'{prefix} line not found once'
    line = lines[idx[0]]; body = line[len(prefix):]; tail = body[len(body.rstrip().rstrip(';')):]
    val = json.loads(body[:len(body) - len(tail)])
    assert prefix + dump(val) + tail == line, f'{prefix} line does not round-trip; not touching it'
    return idx[0], val, tail

for page, want in MEDIA.items():
    p = os.path.join(L, page); lines = open(p, encoding='utf-8').read().split('\n')
    # 1) DATA line: replace only "media" of the meetings that have a video
    i, arr, tail = jline(lines, 'const DATA=', ser)
    keys = {f"{m['n']}|{m['date']}": m for m in arr}
    for k, md in want.items():
        assert k in keys, f'{page}: meeting {k} not on the page'
        keys[k]['media'] = sized(md)
    lines[i] = 'const DATA=' + ser(arr) + tail
    # 2) CAPS line: Thai caption track per video (kept off by default on the page, cc says English is burned in)
    i, caps, tail = jline(lines, 'const CAPS=', lambda a: json.dumps(a, ensure_ascii=False))
    for ck, vtt in CAPK[page].items():
        caps[ck] = open(os.path.join(L, vtt), encoding='utf-8').read()
    lines[i] = 'const CAPS=' + json.dumps(caps, ensure_ascii=False) + tail
    put(p, '\n'.join(lines))
    # 3) the page's meeting list json (indent=1, no final newline, as csite writes it)
    p = os.path.join(L, JSONS[page]); raw = open(p, encoding='utf-8').read(); ms = json.loads(raw)
    assert json.dumps(ms, ensure_ascii=False, indent=1) == raw, f'{JSONS[page]} does not round-trip; not touching it'
    mk = {f"{m['n']}|{m['date']}": m for m in ms}
    for k, md in want.items():
        assert k in mk, f'{JSONS[page]}: meeting {k} missing'
        mk[k]['media'] = sized(md)
    put(p, json.dumps(ms, ensure_ascii=False, indent=1))

# 4) home page: newest-4 video list (same rules as archive/hub/home.py) + Environment 2569 snapshot "v" counts
ms = json.load(open(os.path.join(L, 'meetings.json'), encoding='utf-8'))
p = os.path.join(HUB, 'index.html'); t = open(p, encoding='utf-8').read(); dec = json.JSONDecoder()
mark = 'const HH = '
if t.count(mark) == 1:
    i = t.index(mark) + len(mark); hh, _ = dec.raw_decode(t[i:])
    old_s = ser(hh['videos'])
    assert t.count(old_s) == 1, 'home: video list text not found once'
    law = []
    for m in ms:
        for v in (m.get('media') or {}).get('videos') or []:
            law.append(dict(n=m['n'], date=m['date'], year=2569, who='กมธ.การเกษตรและสหกรณ์', label=v.get('label') or 'วิดีโอสรุป',
                            dur=v.get('dur', ''), poster='agriculture/2569/' + v['poster'] if v.get('poster') else '',
                            headline='' if m.get('pending') else (m.get('headline') or ''), href=f"agriculture/2569/#read-{m['n']}"))
    seen = {(v['href'], v['poster']) for v in hh['videos']}
    vids = hh['videos'] + [v for v in law if (v['href'], v['poster']) not in seen]
    vids.sort(key=lambda v: v['date'], reverse=True)
    t = t.replace(old_s, ser(vids[:4]), 1)
else:
    print('agri_videos: home page has no HH list (skipped)')
dm = 'const DATA = '
assert t.count(dm) == 1, 'home: DATA not found once'
j = t.index(dm) + len(dm); hub, _ = dec.raw_decode(t[j:])
nv = {(m['n'], m['date']): len((m.get('media') or {}).get('videos') or []) for m in ms}
assert any(c.get('id') == 'agriculture' for c in hub), 'home: Agriculture committee not in DATA'
for c in hub:
    if c.get('id') != 'agriculture':
        continue
    for y in c.get('years', []):
        if y.get('year') != 2569:
            continue
        for s in y.get('snap') or []:
            want = nv.get((s['n'], s['date']))
            if want is not None and s.get('v') != want:
                a = ser(s); s['v'] = want; b = ser(s)
                assert t.count(a) == 1, f'home: snapshot entry {s["n"]} not found once'
                t = t.replace(a, b, 1)
put(p, t)
print('agri_videos: changed', len(changed), 'text files:', ', '.join(changed) or 'none (already applied)')
PY

# 5) video share pages + cards (s/v-<n>[-pre].html, s/v-<key>-<n>[-pre].html, img/v/*.jpg; VSHARE map in the pages)
#    CARD_BIG=1 = the live large-text card design (item 18). video_share.py rewrites share pages without the no-download
#    layer, so no_video_dl.py goes straight after (item 21), then the whole-site check.
# Share pages that are already live keep their exact bytes (later layers such as mobile/i18n/seo sit on them); only new
# share pages are added. video_share.py still refreshes the VSHARE map in the archive pages.
KEEP=$(mktemp -d); for f in "$L"/s/v-*.html; do [ -f "$f" ] && cp -p "$f" "$KEEP/"; done
CARD_BIG=1 python3 "$BUILD/video_share.py" "$L" https://parliamentx.com/agriculture/2569 2569
python3 "$BUILD/no_video_dl.py" "$L/s"
# video_share.py writes new share pages without the search tags (canonical, VideoObject); add them now
# (run_bundle.sh runs seo.py bundle again at the end of the bundle; idempotent).
python3 "$BUILD/seo.py" apply "$L"
python3 "$BUILD/no_video_dl.py" --check "$L"
for f in "$KEEP"/v-*.html; do [ -f "$f" ] && cp -p "$f" "$L/s/$(basename "$f")"; done; rm -rf "$KEEP"
for f in v-39 v-39-pre v-38 v-37 v-livestock-20; do test -f "$L/s/$f.html" || { echo "agri_videos: share page s/$f.html missing" >&2; exit 1; }; done
python3 - "$L" <<'PY'
import json, sys
L = sys.argv[1]
for page, ks in (('index.html', ('39', '38', '37')), ('sub-livestock.html', ('20',))):
    t = open(f'{L}/{page}', encoding='utf-8').read()
    vs = [l for l in t.split('\n') if l.startswith('const VSHARE=')]
    assert vs and all(f'"{k}":' in vs[0] for k in ks), f'{page}: VSHARE missing {ks}'
    assert t.count('"kind":"post"') + t.count('"kind":"pre"') >= 2 * {'index.html': 4, 'sub-livestock.html': 1}[page], f'{page}: kind pre/post labels missing'
print('180_agri37_39_live20_post_videos OK')
PY

# 6) videos out of the main site (thread "Site: Move videos to a separate video site", item 90): every linked mp4 moves to the
#    video repos and links are rewritten. Idempotent; run_bundle.sh runs the same step again at the end of the bundle.
#    Push + merge the changed video repos BEFORE the main site (archive/video_repos/README.md).
VR=/mnt/project-files/archive/video_repos
if [ "${I97_TEST_NO_OFFLOAD:-}" = 1 ]; then echo "180_agri37_39_live20_post_videos: offload skipped (sandbox test only)"
else
  test -f $VR/ACTIVE || { echo "180_agri37_39_live20_post_videos: video repos not active yet (needs item 90 first); refusing to leave videos on the main site" >&2; exit 1; }
  grep -qxF '*.mp4' $HUB/.gitignore 2>/dev/null || { echo "180_agri37_39_live20_post_videos: $HUB/.gitignore has no *.mp4 line (needs item 90 first)" >&2; exit 1; }
  python3 "$BUILD/video_offload.py" "$HUB" --report $VR/OFFLOAD_180_agri37_39_live20_post_videos.md
  python3 /mnt/project-files/archive/check/video_host_check.py "$HUB"
  if find "$L" -name '*.mp4' | grep -q .; then echo "180_agri37_39_live20_post_videos: mp4 still on the main site after offload" >&2; exit 1; fi
fi
echo "180_agri37_39_live20_post_videos OK"
